        m_web_view->apply_appearance(dark);
}

void PrinterPanel::on_pump(wxTimerEvent&)
{
    if (!m_web_view)
        return;
    Agent::AgentHost& host = m_web_view->host();
    host.pump_stream();
    host.pump_tools();
    host.pump_setup();
    m_conversation->tick(std::chrono::steady_clock::now());
}

